import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const s="/depgate/diagrams/request-flow.png",m=JSON.parse('{"title":"How DepGate works","description":"","frontmatter":{"aside":false,"pageClass":"dg-wide-page"},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md"}'),i={name:"guide/how-it-works.md"};function n(l,e,d,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="how-depgate-works" tabindex="-1">How DepGate works <a class="header-anchor" href="#how-depgate-works" aria-label="Permalink to &quot;How DepGate works&quot;">​</a></h1><p>This page explains what happens inside DepGate when a package manager asks for a package, and introduces the concepts used throughout the documentation. For where DepGate fits in your environment and how it is deployed, see <a href="./architecture">Architecture</a>.</p><h2 id="the-request-flow" tabindex="-1">The request flow <a class="header-anchor" href="#the-request-flow" aria-label="Permalink to &quot;The request flow&quot;">​</a></h2><p><img src="'+s+'" alt="How a request flows through DepGate"></p><ol><li><strong>Authenticate.</strong> Every request carries a token: a person&#39;s registry token, a CI token, or a service-account key. DepGate records who made each download.</li><li><strong>Pick the repository.</strong> The URL names the ecosystem and the repository, for example <code>https://depgate.example.com/npm/default/</code>. The repository decides which upstream registries are asked.</li><li><strong>Fetch metadata.</strong> DepGate reads the package&#39;s metadata from upstream and caches it in Redis, so popular packages are answered quickly and upstream outages are smoothed over.</li><li><strong>Gather facts.</strong> For the versions being decided, DepGate looks up what the policies need: license, publish date, known vulnerabilities (from <a href="https://osv.dev" target="_blank" rel="noreferrer">OSV</a>), exploit likelihood (<a href="https://www.first.org/epss/" target="_blank" rel="noreferrer">EPSS</a>) and project health (<a href="https://scorecard.dev" target="_blank" rel="noreferrer">OpenSSF Scorecard</a>). Facts are cached too.</li><li><strong>Decide each version.</strong> An allowed file is streamed to the client, or served from the <a href="/depgate/admin/artifact-cache">artifact cache</a> when it is there. A blocked download is refused with HTTP 403 and a reason that names the policy, and a link to Package check.</li></ol><p>Download links in the metadata are rewritten to point at DepGate, so clients never fetch files from the registry directly and cannot bypass the gateway.</p><h2 id="the-order-of-checks" tabindex="-1">The order of checks <a class="header-anchor" href="#the-order-of-checks" aria-label="Permalink to &quot;The order of checks&quot;">​</a></h2><p>For each package version, DepGate applies these checks in order. The first one that decides wins.</p><table tabindex="0"><thead><tr><th>Order</th><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td><strong>Namespace protection.</strong> Is the name one of your internal names, requested from a remote that may not serve it?</td><td>Blocked. Nothing can lift this except an exception scoped to the namespace policy.</td></tr><tr><td>2</td><td><strong>Exceptions.</strong> Is there an active exception for this package and version?</td><td>Allowed.</td></tr><tr><td>3</td><td><strong>Malware list.</strong> Is the package or version a known-malicious package?</td><td>Blocked.</td></tr><tr><td>4</td><td><strong>Policies,</strong> lowest priority number first. Does the version match the policy&#39;s rule?</td><td>The policy&#39;s action: Block or Allow.</td></tr><tr><td>5</td><td>Nothing matched.</td><td>Allowed.</td></tr></tbody></table><p>Policies in <a href="/depgate/admin/monitoring">monitor mode</a> are evaluated too, but they only record what they would have blocked; they never change the result.</p><h2 id="main-concepts" tabindex="-1">Main concepts <a class="header-anchor" href="#main-concepts" aria-label="Permalink to &quot;Main concepts&quot;">​</a></h2><ul><li><strong>Ecosystem</strong>: A package format and its clients: npm, PyPI, Maven, Go, NuGet, Cargo, Composer or RubyGems.</li><li><strong>Repository</strong>: A URL that clients use, such as <code>/npm/default/</code>. A <em>remote</em> repository proxies one upstream registry. A <em>virtual</em> repository combines several remotes behind one URL and asks them in order. Every ecosystem starts with <code>default</code> (the public registry) and <code>all</code> (every enabled remote). See <a href="/depgate/admin/repositories">Repositories</a>.</li><li><strong>Policy</strong>: A rule plus an action. &quot;Block every version with a vulnerability of CVSS 9.0 or higher&quot; is one policy. Each policy has exactly one rule, a priority and an ecosystem, and can be limited to some repositories. See <a href="/depgate/admin/policies">Policies overview</a>.</li><li><strong>Monitor mode</strong>: A Block policy in monitor mode blocks nothing. It records what it would block, so you can review the impact before you enforce it.</li><li><strong>Exception</strong>: A time-bound permission for a package (and optionally specific versions) that would otherwise be blocked. Developers ask for one with a <strong>waiver request</strong>; the security team approves it.</li><li><strong>Decision Ledger</strong>: The record of every download DepGate refused, and why. Changes people make in DepGate are in the <strong>Audit Log</strong>.</li></ul><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><ul><li><strong>User</strong>: developers and anyone who installs packages. Copies registry settings, checks packages and requests waivers.</li><li><strong>Security</strong>: the team that runs DepGate. Also manages policies, exceptions, repositories, people and integrations.</li><li><strong>Service account</strong>: for CI/CD. Cannot sign in; mints download tokens that last at most 1 day.</li></ul><p>See <a href="/depgate/admin/users#roles">Access</a> for what each role can do.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a>: components, what DepGate stops, and deployment scenarios.</li><li><a href="/depgate/admin/create-policy">Create a policy</a>: put the order of checks to work.</li><li><a href="/depgate/admin/monitoring">Monitor before enforcing</a>: roll out new policies safely.</li></ul>',17)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
